@f1 w.request.filler text="just like that in the scene — keeping the rest of the scene"
@r1 w.request.request act=change mood=do words="i meant left, not right, for the dog on the lawn" predicate=meant
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=definite fill=description sort=dog description="the dog on the lawn"
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=drawn.direction value=left operator=eq phase=result

@f1 w.request.filler text="whole scene — the way the drawing looks so far"
